INSERT INTO public.ingredients (
  owner_id,
  name,
  kcal_per_100,
  protein_per_100,
  carbs_per_100,
  fat_per_100,
  cost_per_100,
  market_name,
  brand,
  source_type,
  blv_food_id,
  swissfir_id,
  category,
  reference_unit,
  source_dataset
)
SELECT
  o.owner_id,
  s.name,
  s.kcal_per_100,
  s.protein_per_100,
  s.carbs_per_100,
  s.fat_per_100,
  NULL,
  NULL,
  NULL,
  'blv_generic',
  s.blv_food_id,
  s.swissfir_id,
  s.category,
  s.reference_unit,
  s.source_dataset
FROM seed_data s
CROSS JOIN owner_row o
ON CONFLICT (owner_id, blv_food_id)
DO UPDATE SET
  name = EXCLUDED.name,
  kcal_per_100 = EXCLUDED.kcal_per_100,
  protein_per_100 = EXCLUDED.protein_per_100,
  carbs_per_100 = EXCLUDED.carbs_per_100,
  fat_per_100 = EXCLUDED.fat_per_100,
  swissfir_id = EXCLUDED.swissfir_id,
  category = EXCLUDED.category,
  reference_unit = EXCLUDED.reference_unit,
  source_dataset = EXCLUDED.source_dataset,
  source_type = 'blv_generic';

COMMIT;
